mapper.select:
SELECT id, provider, record_type, external_id, external_version, payload_hash, payload_object_key,
       first_received_at
  FROM external_data.external_record
 WHERE provider = #{provider}
   AND record_type = #{recordType}
   AND external_id = #{externalId}
   AND external_version = #{externalVersion}

mapper.update:
UPDATE external_data.external_record
   SET payload_hash = #{adoptedHash},
       payload_object_key = #{adoptedObjectKey}
 WHERE id = #{id}
   AND payload_hash = #{expectedHash}
